function pointAtEvent(p,ev){const r=$('canvas'+p.side).getBoundingClientRect();const sx=ev.clientX-r.left,sy=ev.clientY-r.top;return {x:(sx-p.x)/p.scale,y:(sy-p.y)/p.scale,sx,sy};}
function ovalHandle(p,q){const e=entry(p),o=R.ovalAt(e.project,p.index);if(!o)return null;const c=Math.cos(o.angle),s=Math.sin(o.angle);const handles={move:[0,0],width:[o.w/2,0],height:[0,o.h/2],rotate:[0,-o.h/2-18/p.scale]};for(const [name,[x,y]]of Object.entries(handles)){const px=o.cx+x*c-y*s,py=o.cy+x*s+y*c;if(Math.hypot(q.x-px,q.y-py)*p.scale<9)return {name,oval:o};}return null;}
