 const pts=U.resolve(e.project,p.index).points,keys=new Set(C.scopeKeys(S.group,S.selected,e.project));let hit=null,bd=11;for(const k of displayKeys()){if(!keys.has(k))continue;const v=pts[k];if(!usablePoint(v)||U.hiddenState(v.visibility)&&!$('showGhosts').checked)continue;const d=Math.hypot(v.x-q.x,v.y-q.y)*p.scale;if(d<bd){bd=d;hit=k;}}
