 document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){stop();if(S.drag)endPointer(S.drag.pane,ev,true);if(S.job)S.job.cancel=true;S.guide=null;setTool('point');return;}if(S.job||document.querySelector('dialog[open]')||/INPUT|TEXTAREA|SELECT/.test(ev.target.tagName))return;try{if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='z'){ev.preventDefault();restoreHistory(ev.shiftKey);return;}if((ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='y'){ev.preventDefault();restoreHistory(true);return;}if(ev.key==='Tab'){ev.preventDefault();const collapse=!$('layout').classList.contains('no-library')||!$('layout').classList.contains('no-inspector');$('layout').classList.toggle('no-library',collapse);$('layout').classList.toggle('no-inspector',collapse);}else if(ev.key===' '){ev.preventDefault();$('play'+S.active).click();}else if(ev.key==='ArrowLeft'||ev.key==='ArrowRight'){ev.preventDefault();stop();seek(pane(),pane().index+(ev.key==='ArrowLeft'?-1:1)*(ev.shiftKey?10:1));}else if(ev.key.toLowerCase()==='h')setTool('pan');else if(ev.key.toLowerCase()==='v')setTool('point');else if(ev.key.toLowerCase()==='f')fitPane(pane());else if(ev.key==='['||ev.key===']'){$('brushSize').value=U.clamp(+$('brushSize').value+(ev.key==='['?-2:2),1,120);text('brushOut',$('brushSize').value+' px');paint(pane());}}catch(e){report(e);}});
