async function playback(timestamp){try{if(!S.job){const linked=$('linkMode').value==='progress',work=Object.values(S.panes).filter(p=>p.playing);const process=linked&&work.length>1?[S.panes.A]:work;for(const p of process){const e=entry(p);if(!e)continue;const dt=Math.min(500,timestamp-(p.last||timestamp));p.last=timestamp;p.clock+=dt/1000*+$('speed').value;let idx=p.index,steps=0,warning=null;while(p.clock>=e.project.frames[idx].duration&&steps<e.project.frames.length){p.clock-=e.project.frames[idx].duration;idx=(idx+1)%e.project.frames.length;steps++;if($('pauseWarning').checked){const f=e.findings.find(f=>f.frame===idx&&f.region===S.group&&f.status==='open'&&f.id!==p.flagPaused);if(f){warning=f;break;}}}if(steps)await seek(p,idx,linked);if(warning){p.flagPaused=warning.id;stop();activate(p.side);setTab('anatomy');status('Paused for review: frame '+(idx+1)+' · '+warning.reasons.join('; '));break;}}if($('pauseDifference').checked&&Object.values(S.panes).some(p=>p.playing)){const a=entry(S.panes.A),b=entry(S.panes.B);if(a&&b){const m=C.compare(S.corpus,a,S.panes.A.index,b,S.panes.B.index,S.group,S.selected),token=a.id+':'+S.panes.A.index+':'+b.id+':'+S.panes.B.index+':'+S.group;if(m.score!==null&&!m.viewMismatch&&!m.bodyTypeMismatch&&m.score>U.clamp(+$('differenceThreshold').value||12,1,100)/100&&S.lastDifferencePause!==token){S.lastDifferencePause=token;stop();setTab('compare');status('Paused for comparison: '+(m.score*100).toFixed(1)+'% projected shape difference. Inspect and classify; different motions may be valid.');}}}}}catch(e){stop();report(e);}requestAnimationFrame(playback);}
async function init(){wire();try{const saved=await DB.load();if(saved){C.validate(saved);S.corpus=C.upgradeKnowledge(saved);text('saveState','Restored from this browser · knowledge layer ready');}else{C.upgradeKnowledge(S.corpus);text('saveState','Local storage ready · knowledge layer ready');} }catch(e){text('saveState','Use Save backup to keep work');$('saveState').classList.add('error');status(e.message,true);}if(!S.corpus.inheritedCorpora.some(x=>x.id===root.CORPUS_CATALOG.corpus_id))S.corpus.inheritedCorpora.push({id:root.CORPUS_CATALOG.corpus_id,manifest:clone(root.CORPUS_CATALOG),importedAt:now(),note:'Index only; media are attached separately.'});renderLibrary();renderInspector();const ids=Object.keys(S.corpus.entries);if(ids[0])await assign('A',ids[0]);if(ids[1])await assign('B',ids[1]);activate('A');S.ready=true;requestAnimationFrame(playback);}
